-- Item 10: durable Simple merchant inbox; no external mail provider is assumed.
-- Append-only events are generated by DB triggers and never block checkout/webhook.
CREATE TABLE IF NOT EXISTS public.simple_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  site_id uuid NOT NULL REFERENCES public.sites(id) ON DELETE CASCADE,
  order_id uuid NULL,
  event_key text NOT NULL,
  kind text NOT NULL CHECK(kind IN ('order','payment','subscription')),
  title text NOT NULL,
  message text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz NULL,
  CONSTRAINT simple_notifications_event_uniq UNIQUE(site_id,event_key),
  CONSTRAINT simple_notifications_event_key_len CHECK(length(event_key) BETWEEN 2 AND 180)
);
CREATE INDEX IF NOT EXISTS simple_notifications_site_recent
  ON public.simple_notifications(site_id,created_at DESC);
ALTER TABLE public.simple_notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.simple_notifications FROM PUBLIC, anon, authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.simple_notifications TO service_role;

-- DB-native event creation: no credentials, no customer address/telephone.
-- Unique event keys make repeated payment-provider webhooks idempotent.
CREATE OR REPLACE FUNCTION public.simple_notification_order_event()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $fn$
DECLARE v_title text;v_message text;v_key text;v_kind text;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.sites s
                WHERE s.id=NEW.site_id AND s.product_tier='simple') THEN
    RETURN NEW;
  END IF;
  IF TG_OP='INSERT' THEN
    v_key:='order:'||NEW.id::text||':created';
    v_kind:='order';v_title:='Pedido recibido';
    v_message:='Se registró el pedido #'||coalesce(NEW.order_number::text,'')||
      '. Revisá su estado y confirmá el pago antes de prepararlo.';
  ELSIF OLD.payment_status IS DISTINCT FROM NEW.payment_status
         AND NEW.payment_status='approved' THEN
    v_key:='order:'||NEW.id::text||':paid';
    v_kind:='payment';v_title:='Pago confirmado';
    v_message:='Mercado Pago confirmó el pago del pedido #'||coalesce(NEW.order_number::text,'')||'.';
  ELSIF OLD.payment_status IS DISTINCT FROM NEW.payment_status
         AND NEW.payment_status IN ('rejected','cancelled','refunded') THEN
    v_key:='order:'||NEW.id::text||':payment:'||NEW.payment_status;
    v_kind:='payment';v_title:='Cambio en el pago';
    v_message:='El pago del pedido #'||coalesce(NEW.order_number::text,'')||
      ' pasó a estado '||NEW.payment_status||'.';
  ELSE
    RETURN NEW;
  END IF;
  INSERT INTO public.simple_notifications(site_id,order_id,event_key,kind,title,message)
    VALUES(NEW.site_id,NEW.id,v_key,v_kind,v_title,v_message)
    ON CONFLICT(site_id,event_key) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Mail/inbox infrastructure cannot alter a paid checkout, stock, or webhook.
  RAISE WARNING 'simple_notification_order_event_failed: %', SQLSTATE;
  RETURN NEW;
END;
$fn$;

CREATE OR REPLACE FUNCTION public.simple_notification_subscription_event()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $fn$
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status OR NOT EXISTS(
    SELECT 1 FROM public.sites s
    WHERE s.id=NEW.site_id AND s.product_tier='simple'
  ) THEN RETURN NEW; END IF;
  INSERT INTO public.simple_notifications(site_id,event_key,kind,title,message)
  VALUES(NEW.site_id,
    'subscription:'||NEW.site_id::text||':'||NEW.status||':'||
      coalesce(NEW.updated_at,now())::text,
    'subscription','Suscripción actualizada',
    'Tu suscripción Simple cambió al estado '||NEW.status||
    '. Revisá Mi plan para conocer los detalles.')
  ON CONFLICT(site_id,event_key) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'simple_notification_subscription_event_failed: %',SQLSTATE;
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS simple_notification_order_insert ON public.orders;
CREATE TRIGGER simple_notification_order_insert
 AFTER INSERT ON public.orders
 FOR EACH ROW EXECUTE FUNCTION public.simple_notification_order_event();

DROP TRIGGER IF EXISTS simple_notification_order_payment ON public.orders;
CREATE TRIGGER simple_notification_order_payment
 AFTER UPDATE OF payment_status ON public.orders
 FOR EACH ROW EXECUTE FUNCTION public.simple_notification_order_event();

DROP TRIGGER IF EXISTS simple_notification_subscription_status ON public.site_subscriptions;
CREATE TRIGGER simple_notification_subscription_status
 AFTER UPDATE OF status ON public.site_subscriptions
 FOR EACH ROW EXECUTE FUNCTION public.simple_notification_subscription_event();

-- Only an active member of the given store can retrieve its event history.
CREATE OR REPLACE FUNCTION public.simple_my_notifications(
  p_site_id uuid, p_limit integer DEFAULT 50
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $fn$
DECLARE v_result jsonb;
BEGIN
  IF NOT public.platform_is_site_member(p_site_id) THEN RAISE EXCEPTION 'SITE_ACCESS_DENIED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sites WHERE id=p_site_id AND product_tier='simple')
    THEN RAISE EXCEPTION 'SIMPLE_SITE_REQUIRED'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id',n.id,'order_id',n.order_id,'kind',n.kind,'title',n.title,
      'message',n.message,'created_at',n.created_at,'read_at',n.read_at)
      ORDER BY n.created_at DESC,n.id DESC),'[]'::jsonb)
   INTO v_result
   FROM (
    SELECT id,order_id,kind,title,message,created_at,read_at
    FROM public.simple_notifications
    WHERE site_id=p_site_id ORDER BY created_at DESC,id DESC
    LIMIT greatest(1,least(coalesce(p_limit,50),100))
   ) n;
  RETURN v_result;
END;
$fn$;

CREATE OR REPLACE FUNCTION public.simple_mark_notification_read(
  p_site_id uuid, p_notification_id uuid
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $fn$
DECLARE v_id uuid;v_read timestamptz;
BEGIN
  IF NOT public.platform_is_site_member(p_site_id) THEN RAISE EXCEPTION 'SITE_ACCESS_DENIED'; END IF;
  UPDATE public.simple_notifications
    SET read_at=coalesce(read_at,now())
    WHERE id=p_notification_id AND site_id=p_site_id
    RETURNING id,read_at INTO v_id,v_read;
  IF v_id IS NULL THEN RAISE EXCEPTION 'NOTIFICATION_NOT_FOUND'; END IF;
  RETURN jsonb_build_object('id',v_id,'read_at',v_read);
END;
$fn$;

REVOKE EXECUTE ON FUNCTION public.simple_notification_order_event() FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.simple_notification_subscription_event() FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.simple_my_notifications(uuid,integer) FROM PUBLIC,anon;
REVOKE EXECUTE ON FUNCTION public.simple_mark_notification_read(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.simple_my_notifications(uuid,integer) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.simple_mark_notification_read(uuid,uuid) TO authenticated,service_role;
